  cors:'CORS',security_headers:'Security Headers',http_trace:'HTTP TRACE',idor:'IDOR',csrf:'CSRF',method_override:'Method Override',mass_assignment:'Mass Assignment',mass_assignment_extended:'Mass Assignment Extended',
